package inventory

import "testing"

func TestLowStockWarehousesOrderedByQuantityAscending(t *testing.T) {
	stock := map[string]int{
		"chengdu": 99, // 未配置，回退默认阈值 10，不算低库存
		"wuhan":   1,
		"xian":    0,
	}
	got := LowStockWarehouses(stock)
	want := []string{"xian", "wuhan"}
	if !equalStrings(got, want) {
		t.Fatalf("LowStockWarehouses = %v, 期望数量升序 %v", got, want)
	}
}

func TestLowStockWarehousesBreaksQuantityTiesByNameAscending(t *testing.T) {
	stock := map[string]int{
		"wuhan":   3,
		"chengdu": 3,
	}
	got := LowStockWarehouses(stock)
	want := []string{"chengdu", "wuhan"}
	if !equalStrings(got, want) {
		t.Fatalf("LowStockWarehouses = %v, 期望同数量按名字升序 %v", got, want)
	}
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
```

